"""配置读写（纯 JSON，零 GUI 依赖）。"""

import json
from pathlib import Path

_DEFAULT_CONFIG = {
    "vtfcmd": "",
    "png_dir": "",
    "vmt_dir": "",
    "size_enabled": True,
    "resize_enabled": True,
    "resize_width": 1024,
    "resize_height": 1024,
    "vtf_version": "7.2",
    "color_format": "DXT1",
    "alpha_format": "DXT5",
    "resize_method": "nearest",
    "resize_filter": "gaussian",
    "preprocess_base": {
        "alpha_enabled": True,
        "alpha_source": "gray",
        "levels_enabled": True,
        "out_black": 0,
        "out_white": 30,
    },
    "preprocess_normal": {
        "alpha_enabled": False,
        "alpha_source": "gray",
        "levels_enabled": False,
        "out_black": 0,
        "out_white": 255,
    },
}


def load_config(config_path):
    """读取配置文件，返回完整配置 dict。文件不存在则返回默认值。"""
    p = Path(config_path)
    if not p.is_file():
        return dict(_DEFAULT_CONFIG)
    try:
        with open(p, encoding="utf-8") as f:
            data = json.load(f)
    except (json.JSONDecodeError, OSError):
        return dict(_DEFAULT_CONFIG)
    merged = dict(_DEFAULT_CONFIG)
    merged.update({k: v for k, v in data.items() if k in _DEFAULT_CONFIG})
    if isinstance(data.get("preprocess_base"), dict):
        merged["preprocess_base"] = {**_DEFAULT_CONFIG["preprocess_base"], **data["preprocess_base"]}
    if isinstance(data.get("preprocess_normal"), dict):
        merged["preprocess_normal"] = {**_DEFAULT_CONFIG["preprocess_normal"], **data["preprocess_normal"]}
    return merged


def save_config(config_path, data):
    """将配置 dict 写入 JSON 文件。"""
    p = Path(config_path)
    p.parent.mkdir(parents=True, exist_ok=True)
    with open(p, "w", encoding="utf-8") as f:
        json.dump(data, f, indent=2, ensure_ascii=False)
